// Minimal Neon Runner implementation
// Targets <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth || 800);
  const H = (canvas.height = canvas.offsetHeight || 400);
  const GRAVITY = 0.6;
  const PLAYER = { x: 50, y: H - 50, w: 30, h: 30, vy: 0, jumping: false };
  let speed = 4;
  let dashTimer = 0;
  let score = 0;
  const obstacles = [];
  const orbs = [];
  let frame = 0;
  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => {
    keys[e.key] = true;
    if (e.key === 'ArrowUp' && !PLAYER.jumping) {
      PLAYER.vy = -12;
      PLAYER.jumping = true;
    }
    if (e.key === 'ArrowRight' && dashTimer === 0) {
      speed = 8;
      dashTimer = 60; // 1 sec at 60fps
    }
  });
  window.addEventListener('keyup', e => (keys[e.key] = false));
  function spawnObstacle() {
    const w = 20 + Math.random() * 30;
    const h = 20 + Math.random() * 30;
    obstacles.push({ x: W, y: H - h, w, h });
  }
  function spawnOrb() {
    const size = 15;
    const y = H - 80 - Math.random() * 150;
    orbs.push({ x: W, y, w: size, h: size, collected: false });
  }
  function update() {
    frame++;
    // Player physics
    PLAYER.vy += GRAVITY;
    PLAYER.y += PLAYER.vy;
    if (PLAYER.y > H - PLAYER.h) {
      PLAYER.y = H - PLAYER.h;
      PLAYER.vy = 0;
      PLAYER.jumping = false;
    }
    // Dash timing
    if (dashTimer > 0) {
      dashTimer--;
      if (dashTimer === 0) speed = 4;
    }
    // Spawn obstacles/orbs
    if (frame % 120 === 0) spawnObstacle(); // every 2 sec
    if (frame % 300 === 0) spawnOrb(); // every 5 sec
    // Move and cull obstacles
    obstacles.forEach(o => (o.x -= speed));
    while (obstacles.length && obstacles[0].x + obstacles[0].w < 0) obstacles.shift();
    // Move and cull orbs
    orbs.forEach(b => (b.x -= speed));
    while (orbs.length && orbs[0].x + orbs[0].w < 0) orbs.shift();
    // Collision detection
    for (const o of obstacles) {
      if (
        PLAYER.x < o.x + o.w &&
        PLAYER.x + PLAYER.w > o.x &&
        PLAYER.y < o.y + o.h &&
        PLAYER.y + PLAYER.h > o.y
      ) {
        // Game over – reset
        alert('Game Over! Score: ' + Math.floor(score));
        location.reload();
        return;
      }
    }
    for (const b of orbs) {
      if (!b.collected &&
        PLAYER.x < b.x + b.w &&
        PLAYER.x + PLAYER.w > b.x &&
        PLAYER.y < b.y + b.h &&
        PLAYER.y + PLAYER.h > b.h + b.y
      ) {
        b.collected = true;
        speed = 6; // temporary boost
        setTimeout(() => (speed = 4), 2000);
      }
    }
    score += 0.02;
  }
  function draw() {
    ctx.clearRect(0, 0, W, H);
    // background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, W, H);
    // player neon square
    ctx.fillStyle = '#0ff';
    ctx.fillRect(PLAYER.x, PLAYER.y, PLAYER.w, PLAYER.h);
    // obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // orbs
    ctx.fillStyle = '#ff0';
    orbs.forEach(b => {
      if (!b.collected) ctx.fillRect(b.x, b.y, b.w, b.h);
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  }
  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
